mapper.select:
SELECT
(SELECT IFNULL(SUM(o1.pay_amount), 0) FROM orders o1
WHERE o1.deleted = 0 AND o1.craftsman_id = #{craftsmanId}
AND o1.status IN ()
AND o1.pay_time >= #{start} AND o1.pay_time < #{end}
) AS salesAmount,

(SELECT COUNT(*) FROM orders o2
WHERE o2.deleted = 0 AND o2.craftsman_id = #{craftsmanId}
AND o2.status IN ()
AND o2.pay_time >= #{start} AND o2.pay_time < #{end}
) AS orderCount,

(SELECT IFNULL(SUM(o3.pay_amount), 0) FROM orders o3
WHERE o3.deleted = 0 AND o3.craftsman_id = #{craftsmanId}
AND o3.status IN ()
AND o3.pay_time >= #{lastStart} AND o3.pay_time < #{lastEnd}
) AS lastMonthAmount,

(SELECT IFNULL(SUM(b1.quota), 0) FROM booking b1
WHERE b1.deleted = 0 AND b1.craftsman_id = #{craftsmanId}
AND b1.status IN ()
AND b1.create_time >= #{start} AND b1.create_time < #{end}
) AS bookingPeople,

(SELECT IFNULL(SUM(g1.view_count), 0) FROM goods g1
WHERE g1.deleted = 0 AND g1.craftsman_id = #{craftsmanId}
) AS goodsViewTotal

SELECT
(SELECT COUNT(*) FROM orders o1
WHERE o1.deleted = 0 AND o1.craftsman_id = #{craftsmanId} AND o1.status = 1
) AS waitDeliverOrders,

(SELECT COUNT(*) FROM booking b1
WHERE b1.deleted = 0 AND b1.craftsman_id = #{craftsmanId} AND b1.status = 0
) AS waitAuditBookings,

(SELECT COUNT(*) FROM orders o2
WHERE o2.deleted = 0 AND o2.craftsman_id = #{craftsmanId} AND o2.refund_status = 1
) AS applyingRefunds,

(SELECT COUNT(*) FROM goods g1
WHERE g1.deleted = 0 AND g1.craftsman_id = #{craftsmanId}
AND g1.status = 1 AND g1.audit_status = 1 AND g1.stock <= #{stockThreshold}
) AS stockWarnGoods,

(SELECT COUNT(*) FROM review r
WHERE r.deleted = 0
AND (r.reply IS NULL OR r.reply = '')
AND (
(r.type = 1 AND EXISTS (SELECT 1 FROM goods g2
WHERE g2.id = r.target_id AND g2.craftsman_id = #{craftsmanId}))
OR (r.type = 2 AND EXISTS (SELECT 1 FROM course c2
WHERE c2.id = r.target_id AND c2.craftsman_id = #{craftsmanId}))
)
) AS unrepliedReviews
